const SUPA='https://gojpffsrxybbpbdzzrvs.supabase.co/rest/v1';
const hdr={ apikey: $credentials.supabaseApi.apiKey, Authorization: `Bearer ${$credentials.supabaseApi.apiKey}` };
const threeWeeksAgo = new Date(Date.now() - 21*86400000).toISOString();
const [staleTasks, overdueLiveBets, leadsAtRisk] = await Promise.all([
  this.helpers.httpRequest({ method:'GET', url:`${SUPA}/tasks?status=neq.done&updated_at=lt.${threeWeeksAgo}&select=title,agent,workstream&limit=20`, headers: hdr, json:true }),
  this.helpers.httpRequest({ method:'GET', url:`${SUPA}/bets?status=eq.live&select=hypothesis,kind,started_at,time_box_days,est_mrr_impact_usd&limit=50`, headers: hdr, json:true }),
  this.helpers.httpRequest({ method:'GET', url:`${SUPA}/leads?status=in.(ready,contacted)&follow_up_at=lt.${new Date().toISOString()}&select=full_name,company,follow_up_at`, headers: hdr, json:true }),
]);
const overdueLive = (overdueLiveBets || []).filter(b => {
  const elapsed = (Date.now() - new Date(b.started_at).getTime()) / (b.time_box_days * 86400000);
  return elapsed >= 0.8;
});
return [{ json: { staleTasks, overdueLive, leadsAtRisk } }];

const t=($input.first().json.content||[]).map(b=>b.text||'').join('').trim();
let pm=null; try{const a=t.indexOf('{'),b=t.lastIndexOf('}');if(a>=0&&b>a)pm=JSON.parse(t.slice(a,b+1))}catch{}
return [{ json: { pm: pm || { risks: [] } } }];
